    BLOG = "/* ===========================================================================\n   blog.css \xE2\x80\x94 the base layer pulpmesh ships with.\n\n   Readable defaults plus the handful of utility classes the templates use. A\n   site's own _styles.css is linked after this file and overrides it.\n   =========================================================================== */\n\n/* The pulpme.sh palette: warm paper in light, near black in dark, both\n   linking in the brand green. */\n:root {\n  --bg: #fbfaf7;\n  --fg: #1c1b19;\n  --dim: #6d6a63;\n  --accent: #0d8250;\n  --link: var(--accent);\n  --rule: #e0ddd4;\n  --pre: #f3f0e9;\n  --code: #ebe8de;\n  /* The wordmark is drawn in neon, which is loud on a pale background. */\n  --logo-adjust: brightness(0.86) saturate(1.15);\n}\n\n@media (prefers-color-scheme: dark) {\n  :root {\n    --bg: #0d0d0f;\n    --fg: #e8e6e1;\n    --dim: #8b8880;\n    --accent: #35d68a;\n    --rule: #24242a;\n    --pre: #16161a;\n    --code: #1f1f26;\n    --logo-adjust: none;\n  }\n}\n\n* {\n  box-sizing: border-box;\n}\n\nhtml {\n  background: var(--bg);\n}\n\nbody {\n  background: var(--bg);\n  color: var(--fg);\n  font-family: system-ui, sans-serif;\n  font-size: 16px;\n  line-height: 1.6;\n  max-width: 720px;\n  margin: 0 auto;\n  padding: 1rem;\n}\n\na,\na:visited {\n  color: var(--link);\n}\n\n::selection {\n  background: var(--accent);\n  color: var(--bg);\n}\n\nh1,\nh2,\nh3,\nh4,\nh5,\nh6 {\n  line-height: 1.25;\n}\n\np {\n  margin: 0 0 1rem;\n}\n\nhr {\n  border: none;\n  border-top: 1px solid var(--rule);\n  margin: 1rem 0;\n}\n\nimg {\n  max-width: 100%;\n}\n\nblockquote {\n  margin: 1rem 0;\n  padding-left: 1rem;\n  border-left: 3px solid var(--rule);\n  color: var(--dim);\n}\n\ntable {\n  border-collapse: collapse;\n}\n\nth,\ntd {\n  border: 1px solid var(--rule);\n  padding: 4px 8px;\n}\n\n/* ---- code -------------------------------------------------------------- */\n/* Code blocks are painted from --pre with !important so a syntax theme's own\n   background can never fight the site theme. */\ncode {\n  font-family: ui-monospace, monospace;\n  background: var(--code);\n  border-radius: 3px;\n  padding: 0 4px;\n}\n\npre {\n  background: var(--pre) !important;\n  padding: 10px 12px;\n  overflow-x: auto;\n}\n\npre code {\n  background: none;\n  padding: 0;\n}\n\n.highlight,\n.highlighter-rouge {\n  background: var(--pre) !important;\n}\n\n/* ---- footer ------------------------------------------------------------ */\nfooter {\n  color: var(--dim);\n  margin-top: 2rem;\n}\n\n/* The feed link trails the footer as a quiet last line. */\nnav.feed {\n  color: var(--dim);\n  margin-top: 1rem;\n}\n\n/* The wordmark in the default footer line. The svg has room above and below\n   the letters, so it is set taller than the text and dropped below the\n   baseline to sit on it. */\n.footer-logo {\n  height: 1.6em;\n  width: auto;\n  vertical-align: -0.45em;\n  filter: var(--logo-adjust);\n}\n\n/* ---- post list --------------------------------------------------------- */\n/* Titles and nav links are uppercased for the terminal-index look; anything\n   carrying real prose opts out with .transform-none. */\n.posts a,\nnav a {\n  text-transform: uppercase;\n  text-decoration: none;\n}\n\n.posts a:hover,\nnav a:hover {\n  text-decoration: underline;\n}\n\n.transform-none,\n.transform-none a {\n  text-transform: none;\n}\n\n.posts {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n}\n\n.posts li {\n  margin: 0.15rem 0;\n}\n\n.post-date {\n  color: var(--dim);\n  margin-right: 0.75rem;\n  white-space: nowrap;\n}\n\n.tags .tag {\n  color: var(--dim);\n  margin-right: 0.5rem;\n}\n\n.tags .tag::before {\n  content: \"#\";\n}\n\n#last-updated {\n  color: var(--dim);\n  margin-top: 1rem;\n}\n\n/* ---- utilities --------------------------------------------------------- */\n.text-sm {\n  font-size: 0.8rem;\n}\n\n.text-md {\n  font-size: 1.15rem;\n}\n\n.text-lg {\n  font-size: 1.35rem;\n}\n\n.text-xl {\n  font-size: 1.5rem;\n}\n\n.text-2xl {\n  font-size: 1.9rem;\n}\n\n.font-bold {\n  font-weight: bold;\n}\n\n.text-center {\n  text-align: center;\n}\n\n.m-0 {\n  margin: 0;\n}\n\n.mt-2 {\n  margin-top: 0.5rem;\n}\n\n.mt-4 {\n  margin-top: 1rem;\n}\n\n.flex {\n  display: flex;\n}\n\n.items-center {\n  align-items: center;\n}\n\n.flex-1 {\n  flex: 1;\n}\n\n.group > * + * {\n  margin-top: 0.1rem;\n}\n".freeze
